INSERT INTO `wp_posts` VALUES (40,0,'2026-08-08 04:56:39','2026-08-08 04:56:39','<p>Celestine Westlake gồm hai tháp căn hộ với hệ tiện ích hiện đại và tầm nhìn hướng Hồ Tây. Dự án phù hợp nhu cầu an cư lâu dài trong khu vực có hạ tầng hoàn thiện.</p><p>Thông tin mẫu được rút gọn để kiểm tra quy trình quản trị nội dung bằng SCF.</p>','Celestine Westlake','Không gian căn hộ cao cấp tại 300 Võ Chí Công, kết nối trực tiếp nhịp sống Hồ Tây.','publish','closed','closed','','celestine-westlake','','','2026-08-08 04:56:39','2026-08-08 04:56:39','',0,'http://reco-group.local/du-an/celestine-westlake/',1,'reco_project','',0);
